def valid(number):
    if not isinstance(number, str):
        return False
    digits = number.replace(' ', '')
    if len(digits) < 2 or not all(c in '0123456789' for c in digits):
        return False
    total = 0
    double = False
    for c in reversed(digits):
        d = ord(c) - 48
        if double:
            d *= 2
            if d > 9:
                d -= 9
        total += d
        double = not double
    return total % 10 == 0
